        evidence: { theorems: ['OAI.PlanarAnderson.ae_bounded', 'OAI.PlanarAnderson.anderson_operator_exists_selfAdjoint', 'OAI.PlanarAnderson.spectrum_subset_spectralInterval_of_norm_le'], taskIds: ['ae_bounded', 'anderson_operator_exists_selfAdjoint', 'anderson_spectrum_subset'], source: { name: 'Submission.lean', line: 224, endLine: 245 } },
