        evidence: { theorems: ['OAI.PlanarAnderson.finite_box_approx_eigenvector_center0_uniform', 'OAI.PlanarAnderson.finite_box_approx_eigenvector', 'OAI.PlanarAnderson.nearConstant_sub_norm_le'], taskIds: ['finite_box_approx_eigenvector'], source: { name: 'Submission.lean', line: 1125, endLine: 1146 } },
